import org.openqa.selenium.By;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import org.testng.Assert;

public class AdminUserTest {
    public static void main(String[] args) {
        WebDriver driver = new ChromeDriver();
        driver.get("https://opensource-demo.orangehrmlive.com/web/index.php/admin/viewSystemUsers");
        driver.findElement(By.xpath("//button[contains(.,'Add')]")).click();
        driver.findElement(By.cssSelector("input[placeholder='Type for hints...']")).sendKeys("Linda Jane Anderson");
        driver.findElement(By.cssSelector("div.oxd-form-row input.oxd-input:not([type='password'])")).sendKeys("qa_valid_user_01");
        driver.findElement(By.cssSelector("button[type='submit']")).click();
        boolean success = driver.getPageSource().contains("Successfully Saved");
        Assert.assertTrue(success);
        driver.quit();
    }
}
